import * as CheckboxPrimitive from "@kobalte/core/checkbox";
import type { PolymorphicProps } from "@kobalte/core/polymorphic";
import type { ValidComponent } from "@solidjs/web";
import { cn } from "~/lib/utils.ts";
import IconCheck from "~icons/ph/check";

import { omit } from "solid-js";

type CheckboxRootProps<T extends ValidComponent = "div"> =
  & CheckboxPrimitive.CheckboxRootProps<T>
  & { class?: string | undefined };

const Checkbox = <T extends ValidComponent = "div">(
  props: PolymorphicProps<T, CheckboxRootProps<T>>,
) => {
  const local = props as CheckboxRootProps;
  const others = omit(local, "class");
  return (
    <CheckboxPrimitive.Root
      data-slot="checkbox"
      class="peer"
      {...others}
    >
      <CheckboxPrimitive.Input class="peer" />
      <CheckboxPrimitive.Control
        class={cn(
          "border-input dark:bg-input/30 data-[checked]:text-primary-foreground data-invalid:border-destructive dark:data-invalid:border-destructive/50 peer-focus-visible:border-ring peer-focus-visible:ring-ring/50 data-invalid:ring-destructive/20 dark:data-invalid:ring-destructive/40 flex size-4 items-center justify-center rounded-[4px] border shadow-xs transition-shadow group-has-disabled/field:opacity-50 data-[checked]:bg-primary dark:data-[checked]:bg-primary data-[checked]:border-primary data-invalid:data-[checked]:border-primary peer-focus-visible:ring-3 data-invalid:ring-3 relative shrink-0 outline-none after:absolute after:-inset-x-3 after:-inset-y-2 data-disabled:cursor-not-allowed data-disabled:opacity-50",
          local.class,
        )}
      >
        <CheckboxPrimitive.Indicator
          data-slot="checkbox-indicator"
          class="[&>svg]:size-3.5 grid place-content-center text-current transition-none"
        >
          <IconCheck
          />
        </CheckboxPrimitive.Indicator>
      </CheckboxPrimitive.Control>
    </CheckboxPrimitive.Root>
  );
};

export { Checkbox };
